<template>
  <XmclAddInstanceDialog :model-value="addDialog" :busy="busy" :execute="execute" @update:model-value="$emit('update:addDialog', $event)" @created="$emit('created')" />
  <XmclTaskCenter v-if="!isPclShell" :busy="busy" :execute="call" :status="status" :snapshot="taskSnapshot" :open="taskCenterOpen" @cancel="$emit('cancel')" @updated="$emit('task-updated', $event)" @closed="$emit('update:taskCenterOpen', false)" />
  <q-dialog :model-value="searchShown" position="top" @update:model-value="$emit('update:searchShown', $event)"><q-card class="global-search text-white"><q-card-section><q-input :model-value="globalSearch" dark outlined autofocus clearable :placeholder="t('xmcl.overlays.search')" @update:model-value="$emit('update:globalSearch', $event)"><template #prepend><q-icon name="search" /></template></q-input></q-card-section><q-list v-if="globalSearch.trim()" separator><q-item v-for="instance in searchResults" :key="instance.id" clickable v-close-popup @click="$emit('search-result', instance)"><q-item-section avatar><q-avatar rounded><img :src="icons[instance.id] || undefined" /></q-avatar></q-item-section><q-item-section><q-item-label>{{ instance.name }}</q-item-label><q-item-label caption>{{ instance.runtime?.minecraft || instance.minecraftVersion || 'Minecraft' }} · {{ instance.group || t('xmcl.overlays.ungrouped') }}</q-item-label></q-item-section><q-item-section side><q-icon name="chevron_right" /></q-item-section></q-item><q-item v-if="!searchResults.length"><q-item-section class="text-grey-5">{{ t('xmcl.overlays.noMatch') }}</q-item-section></q-item></q-list></q-card></q-dialog>
  <PclMsg v-if="isPclShell" :model-value="dialog" :title="prompt" :answer="answer" :choices="choices" :confirmation="confirmation" :secret="secret" @update:answer="$emit('update:answer', $event)" @finish="value => $emit('dialog-finish', value)" />
  <q-dialog v-else :model-value="dialog" persistent @update:model-value="value => !value && $emit('dialog-finish', false)"><q-card class="bg-grey-9 text-white" style="width:520px;max-width:90vw"><q-card-section class="text-h6">{{ prompt }}</q-card-section><q-card-section><q-select v-if="choices" :model-value="answer" dark outlined :options="choices" emit-value map-options :label="t('xmcl.overlays.choose')" @update:model-value="$emit('update:answer', $event)"/><q-input v-else-if="!confirmation" :model-value="answer" dark outlined :type="secret ? 'password' : 'textarea'" autofocus @update:model-value="$emit('update:answer', $event)"/></q-card-section><q-card-actions align="right"><q-btn flat :label="t('xmcl.overlays.cancel')" @click="$emit('dialog-finish', false)"/><q-btn color="primary" :label="t('xmcl.overlays.confirm')" @click="$emit('dialog-finish', true)"/></q-card-actions></q-card></q-dialog>
</template>
<script setup lang="ts">
import XmclAddInstanceDialog from './XmclAddInstanceDialog.vue';
import XmclTaskCenter from './XmclTaskCenter.vue';
import PclMsg from '../pcl/components/PclMsg.vue';
import { useI18n } from 'vue-i18n';
const { t } = useI18n();
defineProps<{ addDialog:boolean; busy:boolean; execute:(op:string,p?:Record<string,unknown>)=>Promise<any>; call:(op:string,p?:Record<string,unknown>)=>Promise<any>; isPclShell:boolean; status:string; taskSnapshot:any; taskCenterOpen:boolean; searchShown:boolean; globalSearch:string; searchResults:any[]; icons:Record<string,string>; dialog:boolean; prompt:string; answer:any; choices:any[]|null; confirmation:boolean; secret:boolean }>();
defineEmits();;
</script>
